"""One Linux synthetic handshake suite only; never invoke production main/data CLI."""
import base64
import gzip
import hashlib
import importlib.util
import json
import os
import resource
import signal
import sys
import tempfile
import time
import unittest
from pathlib import Path

start = time.monotonic()
expected = {'scripts/verify_s8_readonly_p.py': '5320ffe926cf7b56ddf2970b7888f79391e18fb62cf50298127e4eb2af8e5471', 'tests/test_s8_readonly_handshake_linux.py': 'e91375e111638c245dea0729ee0784426693416eff552ffff38cdf76cfaac100'}
payload = ''
if sys.platform != 'linux' or sys.prefix != '/gly/weilin/PRICE-master/venv':
    raise ValueError('Expected existing read-only Linux interpreter')
if os.environ.get('CUDA_VISIBLE_DEVICES') != '':
    raise ValueError('Explicit empty CUDA required')
for key in ('OPENBLAS_NUM_THREADS', 'OMP_NUM_THREADS', 'MKL_NUM_THREADS', 'NUMEXPR_NUM_THREADS', 'VECLIB_MAXIMUM_THREADS'):
    if os.environ.get(key) != '1':
        raise ValueError('Synthetic suite requires one CPU thread')
os.sched_setaffinity(0, {min(os.sched_getaffinity(0))})
resource.setrlimit(resource.RLIMIT_AS, (12*1024**3, 12*1024**3))
root = Path(tempfile.mkdtemp(prefix='s8-handshake-synthetic-v2-20261008-', dir='/tmp')).resolve()
(root/'cases').mkdir()
tempfile.tempdir = str(root/'cases')
files = json.loads(gzip.decompress(base64.b64decode(payload)))
actual = {}
for name, encoded in files.items():
    data = base64.b64decode(encoded)
    path = root/name
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(data)
    actual[name] = hashlib.sha256(path.read_bytes()).hexdigest()
if actual != expected:
    raise ValueError('Synthetic source/test SHA mismatch')
print('S8_LINUX_SYNTHETIC_PRECHECK '+json.dumps({'root':str(root),'source_test_sha256':actual,
      'python':sys.version,'sys_prefix':sys.prefix,'cpu_affinity':sorted(os.sched_getaffinity(0)),
      'CUDA_VISIBLE_DEVICES':os.environ['CUDA_VISIBLE_DEVICES'],
      'RLIMIT_AS_bytes':list(resource.getrlimit(resource.RLIMIT_AS)),
      'old_data_paths_opened':[],'purpose':'helper_synthetic_proc_pipe_not_real_P'},sort_keys=True),flush=True)
spec = importlib.util.spec_from_file_location('test_s8_readonly_handshake_linux', root/'tests/test_s8_readonly_handshake_linux.py')
module = importlib.util.module_from_spec(spec)
spec.loader.exec_module(module)
suite = unittest.defaultTestLoader.loadTestsFromModule(module)


def interrupt_suite(signum, _frame):
    # TestCase records the interruption as an error; fixture finally kills/reaps
    # its own process group, and failfast prevents another scenario from starting.
    raise InterruptedError(f'Linux synthetic suite received signal {signum}')


signal.signal(signal.SIGTERM, interrupt_suite)
signal.signal(signal.SIGINT, interrupt_suite)
result = unittest.TextTestRunner(verbosity=2, failfast=True).run(suite)
after = {name:hashlib.sha256((root/name).read_bytes()).hexdigest() for name in expected}
summary = {'status':'passed_Linux_synthetic_handshake' if result.wasSuccessful() and not result.skipped and after==expected else 'failed',
           'tests_run':result.testsRun,'failures':len(result.failures),'errors':len(result.errors),'skipped':len(result.skipped),
           'seconds':time.monotonic()-start,'source_test_sha256':after,'source_test_unchanged':after==expected,
           'root':str(root),'cpu_affinity':sorted(os.sched_getaffinity(0)),
           'CUDA_VISIBLE_DEVICES':os.environ['CUDA_VISIBLE_DEVICES'],
           'test_scope':'real_proc_pipe_helper_synthetic_not_full_production_data_CLI',
           'real_P_read':False,'smoke_or_training':False,'attempt':1,
           'TERM_cleanup_policy':'InterruptedError_unwind_fixture_finally_then_failfast'}
(root/'integration-result.json').write_text(json.dumps(summary,indent=2)+'\n')
print('S8_LINUX_SYNTHETIC_RESULT '+json.dumps(summary,sort_keys=True),flush=True)
raise SystemExit(0 if summary['status']=='passed_Linux_synthetic_handshake' else 1)
